const SOURCES={dge:{name:'DGE · Position (2024)',url:'https://www.dge.de/wissenschaft/stellungnahmen-und-positionspapiere/positionen/neubewertung-der-position-zu-veganer-ernaehrung/'},nhs:{name:'NHS · The vegan diet',url:'https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/the-vegan-diet/'},nature:{name:'Nature Food · Scarborough et al. (2023)',url:'https://www.nature.com/articles/s43016-023-00795-w'},soy:{name:'Our World in Data · Drivers of deforestation',url:'https://ourworldindata.org/soy'},animals:{name:'EFSA · Welfare of laying hens (2023)',url:'https://www.efsa.europa.eu/en/plain-language-summary/welfare-laying-hens'},vegan:{name:'The Vegan Society · Definition',url:'https://www.vegansociety.com/go-vegan/definition-veganism'},plant:{name:'Hansen (2024) · Biology & Philosophy',url:'https://link.springer.com/article/10.1007/s10539-024-09953-1'},crops:{name:'Jarvis-Campbell (2025) · Ethical Theory and Moral Practice',url:'https://link.springer.com/article/10.1007/s10677-025-10508-w'},processed:{name:'Journal of Food Composition and Analysis (2025)',url:'https://www.sciencedirect.com/science/article/pii/S0889157525006568'},diet:{name:'Nature Food · Umweltwirkungen (2023)',url:'https://www.nature.com/articles/s43016-023-00795-w'}};
const L=(de,en,vi)=>({de,en,vi});
const debates=[
 {id:'protein',cat:'health',confidence:'context',source:'dge',q:L('Bekomme ich vegan genug Protein?','Can you get enough protein as a vegan?','Ăn thuần thực vật có đủ đạm không?'),strong:L('Tierische Lebensmittel liefern viel Protein und manche Nährstoffe sind aus pflanzlichen Quellen schwerer abzudecken.','Animal foods provide plentiful protein, and some nutrients are harder to obtain from plants.','Thịt, trứng, sữa nhiều đạm và một số chất khó đáp ứng hơn từ thực vật.'),answer:L('Ja, mit einer passenden Auswahl und ausreichender Energiezufuhr ist das möglich. Hülsenfrüchte, Soja, Seitan und Vollkorn liefern Protein. Die DGE zählt Protein bei veganer Ernährung dennoch zu den Nährstoffen, auf die man achten sollte.','Yes, with a varied food selection and adequate energy. Legumes, soy, seitan and whole grains provide protein. Germany’s DGE still lists protein as something to pay attention to.','Có thể đủ nếu ăn đa dạng và đủ năng lượng: đậu, đậu nành, mì căn, ngũ cốc. DGE vẫn khuyến nghị chú ý lượng đạm.'),nuance:L('Bedarf hängt u. a. von Aktivität, Alter und Gesundheitszustand ab. Nicht jeder Beispielplan ist bedarfsdeckend.','Needs vary with activity, age and health. A sample menu is not proof of sufficient intake.','Nhu cầu thay đổi theo tuổi, vận động, sức khoẻ. Thực đơn mẫu không chứng minh đã đủ.'),action:L('Baue zu den Hauptmahlzeiten eine gut erkennbare Proteinquelle ein.','Include a clear protein source in your main meals.','Thêm nguồn đạm rõ ràng vào các bữa chính.')},
 {id:'b12',cat:'health',confidence:'strong',source:'dge',q:L('Wenn Veganismus gesund ist, warum B12 ergänzen?','If vegan is healthy, why take B12?','Nếu ăn chay tốt, tại sao phải bổ sung B12?'),strong:L('Eine Ernährung mit verpflichtendem Supplement wirkt weniger unkompliziert als behauptet.','A diet requiring supplementation looks less straightforward than its advocates suggest.','Phải uống thêm B12 nghe có vẻ không tự nhiên và khá phiền.'),answer:L('Die Kritik am Planungsaufwand ist berechtigt. Für eine zuverlässige vegane Ernährung ist die B12-Supplementation jedoch notwendig. Die DGE nennt sie ausdrücklich als Voraussetzung für eine potenziell gesundheitsfördernde vegane Ernährung.','The added planning is real. But reliable vitamin B12 supplementation is essential on a vegan diet. The DGE explicitly lists it as a prerequisite.','Đúng là cần thêm một bước. Nhưng bổ sung B12 đáng tin cậy là điều thiết yếu; DGE nêu rõ đây là điều kiện quan trọng.'),nuance:L('„Natürlich“ ist kein Nährstoffkriterium. Dosierung, individuelle Aufnahme und gegebenenfalls Laborwerte gehören in fachliche Hände.','“Natural” is not a nutritional quality metric. Dosing, absorption and lab checks need qualified input where appropriate.','“Tự nhiên” không đảm bảo đủ dinh dưỡng. Liều dùng, hấp thu và xét nghiệm nên theo hướng dẫn phù hợp.'),action:L('Eine verlässliche B12-Routine festlegen; nicht auf Algen oder unkontrollierte Fermentationsprodukte vertrauen.','Set a reliable B12 routine; do not rely on unverified algae or fermented foods.','Thiết lập thói quen bổ sung B12; đừng dựa vào tảo hay đồ lên men chưa kiểm chứng.')},
 {id:'kids',cat:'health',confidence:'context',source:'dge',q:L('Ist eine vegane Ernährung für Kinder oder Schwangere sicher?','Is a vegan diet safe for children or pregnancy?','Trẻ em hoặc phụ nữ mang thai ăn thuần thực vật có an toàn không?'),strong:L('Nährstoffdefizite können in sensiblen Lebensphasen besonders schwere Folgen haben.','Nutrient shortfalls can have especially serious consequences in vulnerable life stages.','Thiếu chất ở những giai đoạn nhạy cảm có thể ảnh hưởng nghiêm trọng.'),answer:L('Die DGE gibt für Kinder, Jugendliche, Schwangere, Stillende und ältere Menschen wegen eingeschränkter Datenlage keine klare Empfehlung für oder gegen eine vegane Ernährung. Individuelle, qualifizierte Begleitung ist dringend angeraten.','Because evidence is limited, the DGE offers no unequivocal recommendation for or against vegan diets for children, adolescents, pregnant or breastfeeding people and older adults. Qualified support is strongly advised.','Do bằng chứng còn hạn chế, DGE không khẳng định nên hay không nên áp dụng cho trẻ em, người mang thai, cho con bú và người cao tuổi. Cần tư vấn chuyên môn.'),nuance:L('Keine Pauschalentwarnung und kein Pauschalverbot: Alter, Lebenssituation und konkrete Versorgung zählen.','Neither a blanket green light nor a blanket ban: life stage and actual nutrient status matter.','Không nên tuyên bố an toàn tuyệt đối hoặc cấm tuyệt đối; cần xét hoàn cảnh và dinh dưỡng thực tế.'),action:L('In diesen Gruppen immer Fachberatung und geeignete Versorgungskontrolle einplanen.','Plan qualified dietary guidance and appropriate monitoring in these groups.','Nhờ chuyên gia dinh dưỡng và theo dõi sức khoẻ phù hợp.')},
 {id:'soy',cat:'planet',confidence:'strong',source:'soy',q:L('Zerstört Tofu nicht den Regenwald?','Doesn’t tofu destroy the rainforest?','Đậu phụ không phá rừng nhiệt đới sao?'),strong:L('Sojaanbau ist mit Entwaldung und ökologischen Schäden verbunden.','Soy production is associated with deforestation and environmental harm.','Trồng đậu nành có liên quan đến phá rừng và tổn hại môi trường.'),answer:L('Das Problem ist real. Laut einer globalen Analyse für 2018 gingen rund 77 % des Sojas in die Tierfütterung und etwa 7 % direkt in Lebensmittel wie Tofu oder Sojamilch. Tofu ist nicht der Haupttreiber der globalen Sojanachfrage.','The problem is real. In an analysis of global soy use for 2018, about 77% fed livestock, while roughly 7% went to direct foods like tofu and soy milk. Tofu is not the main driver of soy demand.','Vấn đề phá rừng có thật. Phân tích về năm 2018 cho thấy khoảng 77% đậu nành phục vụ chăn nuôi, chỉ khoảng 7% dùng trực tiếp cho món như đậu phụ, sữa đậu nành.'),nuance:L('Landnutzung und Lieferkette eines konkreten Produkts bleiben wichtig. Die Zahlen sind historische globale Anteile, keine aktuelle Einzelproduktbilanz.','Specific supply chains still matter. These are historical global shares, not a current audit of any specific tofu.','Nguồn gốc từng sản phẩm vẫn quan trọng. Đây là số liệu toàn cầu của năm 2018, không phải kiểm định sản phẩm hôm nay.'),action:L('Beim Einkauf Herkunft und Lieferkettentransparenz vergleichen — und nicht Soja für Tierfutter mit Tofu verwechseln.','Look at sourcing and supply-chain transparency; distinguish livestock feed from direct human soy foods.','Kiểm tra nguồn gốc sản phẩm; phân biệt đậu nành làm thức ăn chăn nuôi và món đậu nành cho người.')},
 {id:'climate',cat:'planet',confidence:'strong',source:'nature',q:L('Ist regionales Fleisch nicht klimafreundlicher als importierter Tofu?','Is local meat greener than imported tofu?','Thịt địa phương có xanh hơn đậu phụ nhập khẩu không?'),strong:L('Regionalität, Transportwege und Produktionsmethoden machen einen Unterschied.','Transport, sourcing and farming methods do make a difference.','Vận chuyển, nguồn gốc và cách sản xuất đều có ảnh hưởng.'),answer:L('Im Durchschnitt zeigen Lebenszyklusanalysen deutliche Umweltvorteile veganer Ernährung. In einer Nature-Food-Studie lag ihr Treibhausgas-Fußabdruck bei rund 25 % des Werts fleischreicher Ernährung.','On average, life-cycle studies show substantial environmental advantages for vegan diets. In a Nature Food study, their greenhouse-gas impact was around 25% of that for high-meat diets.','Nhìn chung, phân tích vòng đời cho thấy thực đơn thuần thực vật ít gây tác động hơn. Một nghiên cứu trên Nature Food ước tính phát thải khoảng 25% so với nhóm ăn nhiều thịt.'),nuance:L('Das ist ein Gruppenvergleich und kein Freibrief für jedes einzelne Produkt; Flugware, Treibhausanbau oder spezifische Weidesysteme erfordern gesonderte Betrachtung.','This is a group comparison, not a guarantee about every product. Individual supply chains and systems vary.','Đây là so sánh giữa các nhóm, không phải mọi sản phẩm thuần thực vật đều tốt hơn trong mọi hoàn cảnh.'),action:L('Bei Klima-Fragen zuerst Lebensmittelart und Produktionssystem vergleichen, dann Transport.','Compare food type and production system first, then transport.','Ưu tiên so sánh loại thực phẩm và cách sản xuất, sau đó mới đến vận chuyển.')},
 {id:'crops',cat:'ethics',confidence:'open',source:'crops',q:L('Sterben beim Pflanzenanbau nicht auch Tiere?','Don’t animals die in crop farming too?','Trồng trọt cũng làm động vật chết mà?'),strong:L('Ernte, Pestizide und Flächenumwandlung können Wildtiere und Insekten töten. Auch vegane Systeme sind nicht schadensfrei.','Harvesting, pesticides and habitat conversion can kill wild animals and insects. Plant agriculture is not harm-free.','Thu hoạch, thuốc trừ sâu, phá môi trường sống cũng gây chết động vật hoang dã, côn trùng.'),answer:L('Ja. Veganismus kann keine Null-Schaden-Garantie geben. Die entscheidende Vergleichsfrage lautet, wie wir vermeidbares Leid und Flächennutzung über das gesamte Ernährungssystem reduzieren.','Yes. Veganism does not promise zero harm. The useful comparison is which food systems reduce avoidable harm and land use overall.','Đúng vậy. Ăn thuần thực vật không đồng nghĩa với không gây hại. Nên so sánh mức tổn hại có thể tránh và tổng diện tích sử dụng.'),nuance:L('Belastbare globale Zahlen zu individuellen Erntetoden fehlen; die moralische Abwägung absichtlicher und unbeabsichtigter Schäden ist umstritten.','Robust global counts of crop-related animal deaths are missing, and the moral distinction between intentional and incidental harm is contested.','Chưa có số liệu toàn cầu chắc chắn về số động vật chết khi trồng trọt; việc đánh giá tổn hại cố ý và vô ý vẫn còn tranh luận.'),action:L('Vermeidung unnötiger Schäden auch in pflanzlicher Landwirtschaft unterstützen — nicht Perfektion behaupten.','Support lower-harm plant farming too; do not claim purity.','Ủng hộ nông nghiệp trồng trọt giảm gây hại, không tự nhận hoàn hảo.')},
 {id:'plants',cat:'ethics',confidence:'open',source:'plant',q:L('Aber Pflanzen haben doch auch Gefühle?','But plants have feelings too, right?','Thực vật cũng biết đau phải không?'),strong:L('Pflanzen reagieren komplex auf ihre Umwelt. Wir sollten die Frage nach Empfindungsfähigkeit nicht einfach lächerlich machen.','Plants respond in complex ways to their environment. Sentience is a serious research question.','Thực vật phản ứng phức tạp với môi trường. Cảm nhận chủ quan là câu hỏi đáng nghiên cứu.'),answer:L('Eine wissenschaftlich-philosophische Übersicht von 2024 findet derzeit keine belastbare Evidenz für pflanzliche Empfindungsfähigkeit. Reaktion auf Reize allein belegt kein subjektives Erleben.','A 2024 critical review finds no evidence currently establishing plant sentience. Responding to stimuli alone does not demonstrate subjective experience.','Một tổng quan năm 2024 cho rằng hiện chưa có bằng chứng chứng minh thực vật có trải nghiệm chủ quan. Phản ứng kích thích chưa chứng tỏ biết đau.'),nuance:L('„Nicht nachgewiesen“ bedeutet nicht logisch „für immer ausgeschlossen“. Der Begriff Bewusstsein bleibt schwierig.','Lack of evidence is not proof of logical impossibility; consciousness remains difficult to study.','Chưa có bằng chứng không có nghĩa là bất khả thi mãi mãi; ý thức là vấn đề khó.'),action:L('Mitgefühl nicht als Wettbewerb zwischen Lebewesen formulieren; Schäden möglichst verringern.','Avoid turning compassion into a contest; aim to reduce harm.','Không biến lòng thương thành cuộc thi; hãy tìm cách giảm tổn hại.')},
 {id:'eggs',cat:'ethics',confidence:'ethic',source:'animals',q:L('Was ist an Eiern aus guter Haltung falsch?','What is wrong with well-raised eggs?','Trứng từ gà nuôi tốt thì có gì sai?'),strong:L('Nicht jede Haltungsform verursacht gleich viel Leid. Gute Haltung kann messbar bessere Tierwohlbedingungen bieten.','Husbandry systems differ; welfare improvements can meaningfully reduce suffering.','Điều kiện nuôi khác nhau và cải thiện phúc lợi động vật có thể giảm khổ đau.'),answer:L('Wissenschaft kann die Folgen unterschiedlicher Haltungssysteme untersuchen. Die EFSA dokumentiert zahlreiche Wohlergehensrisiken bei Legehennen. Ob selbst eine gut behandelte Henne für ihre Eier genutzt werden darf, ist eine separate ethische Frage.','Science can compare welfare outcomes. EFSA documents significant welfare concerns for laying hens. Whether using an otherwise well-treated hen for eggs is acceptable remains an ethical question.','Khoa học có thể đánh giá điều kiện sống. EFSA ghi nhận nhiều rủi ro đối với gà đẻ. Việc sử dụng trứng của gà được chăm tốt có đúng hay không vẫn là câu hỏi đạo đức.'),nuance:L('Der Nachweis eines Problems in einem System belegt nicht identische Probleme in jedem Betrieb.','Problems in a farming system do not imply identical conditions on every farm.','Không thể suy ra mọi trang trại đều gây hại như nhau.'),action:L('Trenne Tierwohl-Fakten von deiner ethischen Grundsatzentscheidung.','Separate welfare evidence from your underlying ethical stance.','Phân biệt bằng chứng phúc lợi động vật và lựa chọn đạo đức cá nhân.')},
 {id:'money',cat:'society',confidence:'context',source:'nhs',q:L('Ist vegan essen nicht zu teuer?','Isn’t eating vegan expensive?','Ăn thuần thực vật chẳng phải rất đắt sao?'),strong:L('Ersatzkäse, Spezialprodukte, angereicherte Alternativen und manche Supplements können teuer sein; Zeit und Zugang sind ungleich verteilt.','Specialty replacements, fortified products and some supplements cost money. Time and access are unequal.','Đồ thay thế chuyên dụng, thực phẩm bổ sung và thời gian chuẩn bị có thể tốn kém.'),answer:L('Viele Grundnahrungsmittel — etwa Hafer, Linsen, Reis, Bohnen — sind oft preiswert. Eine vegane Ernährung muss nicht aus Marken-Ersatzprodukten bestehen.','Staples such as oats, lentils, rice and beans can be affordable. A vegan diet need not revolve around premium substitutes.','Những món cơ bản như yến mạch, đậu, gạo thường vừa túi tiền. Không nhất thiết phải mua đồ thay thế đắt đỏ.'),nuance:L('Preise unterscheiden sich nach Ort, Zugang, Alltagsbelastung und verfügbaren Küchenmöglichkeiten.','Actual affordability depends on location, access, available cooking space and time.','Giá cả còn tuỳ nơi ở, thu nhập, thời gian và khả năng nấu nướng.'),action:L('Starte mit fünf günstigen Staples und zwei Gerichten, die du wirklich magst.','Start with five inexpensive staples and two meals you genuinely like.','Bắt đầu với năm nguyên liệu bình dân và hai món bạn thật sự thích.')},
 {id:'processed',cat:'health',confidence:'context',source:'processed',q:L('Sind vegane Ersatzprodukte nicht ultraverarbeitet?','Aren’t vegan substitutes ultra-processed?','Đồ chay thay thịt chẳng phải chế biến quá nhiều sao?'),strong:L('Manche Alternativen enthalten viel Salz oder weitere Zutaten. „Vegan“ heißt nicht automatisch „gesund“.','Some alternatives are high in salt and additives. “Vegan” does not automatically mean “healthy”.','Một số đồ thay thế có nhiều muối, phụ gia. “Thuần thực vật” không đồng nghĩa “lành mạnh”.'),answer:L('Man muss konkrete Produkte und Verwendungszwecke vergleichen. Eine Übersichtsarbeit von 2025 zeigt, dass pflanzliche Fleischalternativen nährstoffreich sein können, aber ihr Profil je nach Proteinquelle und Rezeptur stark variiert.','Compare actual products, not labels. A 2025 review finds plant-based meat alternatives can be nutrient-dense, but composition varies widely by source and formulation.','Cần so sánh từng sản phẩm. Tổng quan năm 2025 cho thấy đồ thay thịt từ thực vật có thể giàu dinh dưỡng nhưng thành phần rất khác nhau.'),nuance:L('Langfristige gesundheitliche Effekte bestimmter Produktkategorien sind weniger klar als einzelne Nährwerttabellen.','Long-term health outcomes for specific categories are less certain than ingredient lists might suggest.','Tác động sức khoẻ dài hạn của từng loại sản phẩm chưa được hiểu rõ đầy đủ.'),action:L('Auf Salz, gesättigte Fette, Protein, Ballaststoffe und Anreicherung schauen — dann kosten.','Check salt, saturated fat, protein, fibre and fortification, then taste.','Xem muối, chất béo bão hoà, đạm, chất xơ, vi chất bổ sung — rồi ăn thử.')},
 {id:'tradition',cat:'society',confidence:'ethic',source:'vegan',q:L('Muss ich meine Esskultur aufgeben?','Do I need to give up my food culture?','Phải từ bỏ ẩm thực truyền thống sao?'),strong:L('Gerichte verbinden Familien, Erinnerungen und Identität. Diese Bindungen verdienen Respekt.','Food connects families, memories and identity. Those ties deserve respect.','Món ăn gắn với gia đình, ký ức, bản sắc. Những mối liên hệ đó rất đáng trân trọng.'),answer:L('Nein. Man kann Traditionen neu interpretieren: Phở chay, Bún đậu, Tofu mit Zitronengras, Pilz-Bánh-mì. Kultur lebt auch durch Veränderung.','No. Traditions can evolve: phở chay, bún đậu, lemongrass tofu, mushroom bánh mì. Food culture has always changed.','Không. Có phở chay, bún đậu, đậu hũ sả, bánh mì nấm. Ẩm thực luôn thay đổi và sáng tạo.'),nuance:L('Nicht jeder Ersatz schmeckt wie das Original. Verbindungen zu Angehörigen sind wichtiger als ein Reinheitswettbewerb.','Not every swap tastes identical. Family relationships matter more than purity contests.','Không phải món thay thế nào cũng giống bản gốc. Mối quan hệ với gia đình quan trọng hơn thi đua “thuần chay hoàn hảo”.'),action:L('Veganisiere zuerst ein Gericht, das bereits zu deiner Familie gehört.','Start by adapting one dish your family already loves.','Hãy làm phiên bản chay của một món cả nhà vốn yêu thích.')},
 {id:'nature',cat:'ethics',confidence:'ethic',source:'vegan',q:L('Aber Löwen essen doch auch Fleisch?','But lions eat meat too, don’t they?','Nhưng sư tử cũng ăn thịt mà?'),strong:L('Menschen sind Teil der Natur; tierisches Fressen ist in vielen Ökosystemen normal.','Humans are part of nature; predation is normal in many ecosystems.','Con người thuộc về tự nhiên; săn mồi là một phần bình thường của nhiều hệ sinh thái.'),answer:L('Die Frage ist nicht, ob etwas in der Natur geschieht, sondern welche Handlungsalternativen wir als Menschen haben und welche Folgen wir ethisch akzeptieren.','The question is not whether something happens in nature, but what alternatives we humans have and what consequences we regard as acceptable.','Câu hỏi không phải điều gì xảy ra trong thiên nhiên, mà là con người có lựa chọn nào và chấp nhận hậu quả đạo đức nào.'),nuance:L('Menschen leben unter sehr verschiedenen Bedingungen. „Möglich und praktikabel“ ist nicht überall dasselbe.','People live under very different conditions; “possible and practicable” is context-dependent.','Hoàn cảnh của mỗi người khác nhau; “có thể và thực tế” không giống nhau ở mọi nơi.'),action:L('Entscheide anhand deiner realen Alternativen, nicht anhand des Speiseplans eines Löwen.','Choose based on your actual options, not a lion’s menu.','Hãy chọn theo hoàn cảnh mình, đừng dựa vào thực đơn của sư tử.')},
 {id:'tofu',cat:'fun',confidence:'taste',source:'nhs',q:L('Aber Tofu schmeckt doch nach nichts?!','But tofu tastes like nothing?!','Đậu phụ nhạt nhẽo lắm mà?!'),strong:L('Schlecht zubereiteter Tofu ist tatsächlich manchmal eine traurige Angelegenheit.','Badly cooked tofu can genuinely be a sad affair.','Đậu phụ nấu dở thì cũng… buồn thật.'),answer:L('Ein sehr valider Küchen-Einwand. Tofu nimmt Marinaden gut auf und kann durch Auspressen, Anbraten und Würzen ganz unterschiedliche Texturen bekommen. Das ist eine Kochfrage, keine Laborfrage.','A fair culinary objection! Pressing, crisping and marinating can transform tofu. This is a cooking question, not a scientific certainty.','Phản biện hợp lý về chuyện bếp núc! Đậu phụ rán giòn, ướp sả ớt, kho nấm, sốt cà chua có thể rất ngon.'),nuance:L('Geschmack bleibt persönlich. Niemand muss jedes vegane Produkt mögen.','Taste is personal. You do not need to like every vegan product.','Khẩu vị là chuyện cá nhân. Không ai bắt buộc phải thích mọi món chay.'),action:L('Probiere knusprigen Tofu mit Soja-Limetten-Marinade.','Try crispy tofu with soy-lime marinade.','Thử đậu phụ chiên giòn với sả, nước tương và chanh.')},
 {id:'honey',cat:'ethics',confidence:'ethic',source:'vegan',q:L('Was ist eigentlich an Honig un-vegan?','Why is honey not vegan?','Vì sao mật ong không được xem là thuần chay?'),strong:L('Imkerei kann Bestäubung unterstützen; Honig ist im Vergleich zu anderen Tierprodukten ein anders gelagerter Fall.','Beekeeping can contribute to pollination; honey poses different questions from meat.','Nuôi ong có thể giúp thụ phấn; mật ong khác với thịt về mức độ và loại tác động.'),answer:L('Die gängige Definition von Veganismus schließt die Nutzung von Tieren und ihrer Produkte möglichst aus; dazu gehört Honig. Das ist primär eine ethische Einordnung, keine Behauptung über identisches Leid.','Mainstream ethical veganism aims to avoid using animals and their products as far as practicable, including honey. This is primarily an ethical position, not a claim of identical harm.','Định nghĩa thuần chay phổ biến tránh khai thác động vật, bao gồm cả mật ong. Đây chủ yếu là lập trường đạo đức, không phải tuyên bố mọi trường hợp gây hại như nhau.'),nuance:L('Wie einzelne Imkereiformen ökologisch wirken, ist eine separate empirische Frage.','The ecological effects of particular beekeeping practices are a separate empirical question.','Tác động môi trường của từng cách nuôi ong là câu hỏi khoa học riêng.'),action:L('Entscheide transparent nach Werten; Ahornsirup oder Dattelsirup können praktische Alternativen sein.','Be transparent about your values; maple or date syrup are practical alternatives.','Chọn theo giá trị của mình; si-rô lá phong hoặc chà là là lựa chọn thay thế.')}
];
